import{_ as t,o as r,c as a,ag as o}from"./chunks/framework.D1K3FKSn.js";const m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/guide/introduction.html"}],["meta",{"property":"og:title","content":"Introduction | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/guide/introduction.html"}],["meta",{"name":"twitter:title","content":"Introduction | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),n={name:"guide/introduction.md"};function i(d,e,l,c,s,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Kiln is a WebGPU-native, out-of-core volume renderer for large volumetric datasets. It streams multi-gigabyte volumes over HTTP into a bounded GPU residency/atlas cache, resolving them through virtual-texture indirection.</p><p>Kiln streams <a href="/data/ome-zarr.html">OME-Zarr</a> (NGFF v0.4/v0.5) datasets directly — single-channel and multichannel, up to 4 channels — as well as a compressed <a href="/data/sharded-binary.html">sharded binary format</a>. Input can be <code>uint8</code>, <code>uint16</code>, or <code>float32</code>; <code>uint16</code> and <code>float32</code> are converted to <code>r16float</code> for GPU storage.</p><h2 id="where-to-next" tabindex="-1">Where to next <a class="header-anchor" href="#where-to-next" aria-label="Permalink to &quot;Where to next&quot;">​</a></h2><ul><li><strong><a href="/guide/quick-start.html">Quick start</a></strong> — get a viewer rendering a streamed volume in a few lines.</li><li><strong><a href="/guide/loading-data.html">Loading data</a></strong> — remote OME-Zarr, local files, and multichannel datasets.</li><li><strong><a href="/guide/url-parameters.html">URL parameters</a></strong> — share and bookmark specific views.</li><li><strong><a href="/gallery.html">Gallery</a></strong> — live example datasets, each opening directly in the viewer.</li><li><strong><a href="/architecture/overview.html">Architecture</a></strong> — how the virtual texturing and streaming systems work.</li></ul>',5)])])}const g=t(n,[["render",i]]);export{m as __pageData,g as default};
